<div id="analisis-comercial" class="mt-6 rounded-xl bg-white shadow-sm ring-1 ring-gray-950/5 dark:bg-gray-900 dark:ring-white/10">
    <div class="border-b border-gray-200 px-6 py-4 dark:border-white/10"><h3 class="font-semibold">Análisis comercial mensual</h3><p class="text-sm text-gray-500">Información consultada de forma independiente.</p></div>
    <div class="flex flex-col gap-3 px-4 py-4 sm:flex-row sm:items-center sm:justify-between"><div class="flex flex-wrap gap-2"><button data-tipo="vendidos" class="rounded-lg bg-primary-600 px-3 py-2 text-sm font-medium text-white">Más vendidos</button><button data-tipo="rentables" class="rounded-lg bg-gray-100 px-3 py-2 text-sm font-medium text-gray-700 dark:bg-gray-800 dark:text-gray-200">Más rentables</button><button data-tipo="clientes" class="rounded-lg bg-gray-100 px-3 py-2 text-sm font-medium text-gray-700 dark:bg-gray-800 dark:text-gray-200">Clientes</button><button data-tipo="resumen" class="rounded-lg bg-gray-100 px-3 py-2 text-sm font-medium text-gray-700 dark:bg-gray-800 dark:text-gray-200">Resumen</button></div><input aria-label="Mes del análisis" type="month" value="{{ now()->format('Y-m') }}" class="rounded-lg border-gray-300 bg-white text-sm text-gray-900 dark:border-gray-700 dark:bg-gray-800 dark:text-white"></div>
    <div class="overflow-x-auto px-6 pb-5"><table class="w-full text-sm"><thead></thead><tbody><tr><td class="py-4 text-gray-500">Cargando análisis…</td></tr></tbody></table></div>
</div>
<script>
(() => { const root=document.getElementById('analisis-comercial'); if(!root)return; const gain=[...document.querySelectorAll('.fi-wi-widget')].find(x=>x.textContent.includes('Ganancia mensual')); if(gain)gain.after(root); const h=root.querySelector('thead'),b=root.querySelector('tbody'),m=root.querySelector('input'),esc=x=>String(x??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); let t='vendidos'; const product=p=>`<td class="border-b px-3 py-2"><div class="flex items-center gap-3"><div class="h-10 w-10 overflow-hidden rounded-lg bg-gray-100 dark:bg-gray-800">${p[2]?`<img src="${esc(p[2])}" class="h-full w-full object-cover">`:'<span class="flex h-full items-center justify-center">📦</span>'}</div><div><div class="font-semibold">${esc(p[0])}</div><div class="text-xs text-gray-500 dark:text-gray-400">${esc(p[1])}</div></div></div></td>`; const load=async()=>{try{const r=await fetch(`{{ route('analisis-comercial.datos') }}?tipo=${t}&periodo=${m.value}`,{headers:{Accept:'application/json'}});if(!r.ok)throw 0;const d=await r.json();h.innerHTML='<tr>'+d.columnas.map(x=>`<th class="border-y px-3 py-2 text-left text-xs uppercase text-gray-500 dark:text-gray-400">${esc(x)}</th>`).join('')+'</tr>';b.innerHTML=d.filas.length?d.filas.map(row=>{if(row.producto)return '<tr>'+product(row.producto)+row.celdas.map(x=>`<td class="border-b px-3 py-2 text-right">${esc(x)}</td>`).join('')+'</tr>';return '<tr>'+row.map(x=>`<td class="border-b px-3 py-2">${esc(x)}</td>`).join('')+'</tr>'}).join(''):`<tr><td colspan="${d.columnas.length}" class="py-4 text-gray-500">No hay datos para este mes.</td></tr>`}catch(e){h.innerHTML='';b.innerHTML='<tr><td class="py-4 text-gray-500">No se pudo cargar el análisis.</td></tr>'}};root.querySelectorAll('button').forEach(x=>x.onclick=()=>{t=x.dataset.tipo;root.querySelectorAll('button').forEach(y=>y.className='rounded-lg bg-gray-100 px-3 py-2 text-sm font-medium text-gray-700 dark:bg-gray-800 dark:text-gray-200');x.className='rounded-lg bg-primary-600 px-3 py-2 text-sm font-medium text-white';load()});m.onchange=load;load()})();
</script>
